export function carnotPoints(hot,cold){const gamma=5/3,V1=1,V2=1.8,V3=V2*Math.pow(hot/cold,1/(gamma-1)),V4=V3/V2,out=[];for(let j=0;j<4;j++)for(let i=0;i<60;i++){const u=i/59;let V,pressure;if(j===0){V=V1+(V2-V1)*u;pressure=hot/V;}if(j===1){V=V2+(V3-V2)*u;pressure=hot*V2**(gamma-1)/V**gamma;}if(j===2){V=V3+(V4-V3)*u;pressure=cold/V;}if(j===3){V=V4+(V1-V4)*u;pressure=cold*V4**(gamma-1)/V**gamma;}out.push({V,P:pressure,segment:j});}return out;}
