function tunnel(c,w,h,s,t){const v=s.values,a=v.barrierWidth,p=plot(c,w*.16,h*.15,w*.69,h*.23,{xmin:-2,xmax:5,ymin:0,ymax:2.4,xlabel:'x',ylabel:'V, E'});path(c,[[p.X(-2),p.Y(0)],[p.X(0),p.Y(0)],[p.X(0),p.Y(2)],[p.X(a),p.Y(2)],[p.X(a),p.Y(0)],[p.X(5),p.Y(0)]],C.ink,2);dashed(c,[[p.X(-2),p.Y(v.energy)],[p.X(5),p.Y(v.energy)]],C.rose);label(c,'E',p.X(-1),p.Y(v.energy)-7,C.rose);label(c,'V₀',p.X(a/2),p.Y(2)-8,C.ink);
 const wave=plot(c,w*.16,h*.56,w*.69,h*.23,{xmin:-2,xmax:5,ymin:-2.1,ymax:2.1,xlabel:'x',ylabel:'Re Ψ'});wave.curve(x=>P.barrierWave(x,v.energy,2,a,t*.35).re,C.mint,1.8);dashed(c,[[wave.X(0),wave.Y(-2.1)],[wave.X(0),wave.Y(2.1)]]);dashed(c,[[wave.X(a),wave.Y(-2.1)],[wave.X(a),wave.Y(2.1)]]);
 caption(c,`R + T = 1. Transmission: ${(P.transmission(v.energy,2,a)*100).toFixed(1)}%. Continuous wave at both boundaries.`,w,h);}
function curvature(c,w,h,s,t){const v=s.values,rs=v.mass*.12,b=v.impact,scale=Math.min(w*.8/26,h*.65/11),cx=w*.5,cy=h*.75,X=x=>cx+x*scale,Y=y=>cy-y*scale,pts=[];for(let x=-13;x<=13;x+=.1)pts.push([X(x),Y(P.weakFieldRay(x,rs,b))]);dashed(c,[[X(-13),Y(b)],[X(13),Y(b)]]);path(c,pts,C.gold,2);for(let i=0;i<4;i++){const idx=Math.floor((t*.12+i/4)%1*(pts.length-1));dot(c,...pts[idx],3,C.gold);}ball(c,cx,cy,9+v.mass*4,C.ink);dashed(c,[[cx,cy],[cx,Y(b)]]);label(c,'b',cx-10,(cy+Y(b))/2,C.muted);label(c,'M',cx,cy+30,C.ink,14);label(c,`α ≈ ${(P.lightDeflection(rs,b)*180/Math.PI).toFixed(2)}°`,w*.77,h*.84,C.gold,14);caption(c,'Weak-field ray in an ordinary x–y plane. Dashed line: undeflected path.',w,h);}
function clocks(c,w,h,s,t){const near={x:w*.33,y:h*(.65-.04*s.values.radius)},far={x:w*.75,y:h*.3};for(const [p,time,color]of [[near,s.clockNear,C.rose],[far,t,C.mint]]){dot(c,p.x,p.y,30,color,false);for(let i=0;i<12;i++){const a=i*Math.PI/6;path(c,[[p.x+Math.cos(a)*24,p.y+Math.sin(a)*24],[p.x+Math.cos(a)*28,p.y+Math.sin(a)*28]],color,1);}arrow(c,p.x,p.y,Math.sin(time*Math.PI/2)*21,-Math.cos(time*Math.PI/2)*21,color,2);dot(c,p.x,p.y,2,color);}
 ball(c,w*.33,h*.8,16,C.ink);dashed(c,[[near.x,near.y+31],[near.x,h*.8-16]]);label(c,`r = ${s.values.radius.toFixed(1)} rs`,w*.33-15,(near.y+h*.8)/2,C.rose,12,'right');label(c,'Local clock',near.x,near.y-48,C.rose,13);label(c,'Reference at infinity',far.x,far.y-48,C.mint,13);label(c,`τ = ${s.clockNear.toFixed(1)} s`,near.x,near.y+57,C.rose,14);label(c,`t = ${t.toFixed(1)} s`,far.x,far.y+57,C.mint,14);caption(c,'Closer static clocks accumulate less proper time per distant second.',w,h);}
function galaxy(c,w,h,s){const rmax=3,cx=w*.3,cy=h*.43,radius=Math.min(w*.23,h*.28),X=(r,a)=>cx+Math.cos(a)*r/rmax*radius,Y=(r,a)=>cy+Math.sin(a)*r/rmax*radius;for(let i=1;i<=3;i++)dot(c,cx,cy,radius*i/3,C.line,false);if(s.values.halo>0){c.setLineDash([4,5]);dot(c,cx,cy,radius*1.1,C.violet,false);c.setLineDash([]);}for(const star of s.galaxyStars){dot(c,X(star.r,star.angle),Y(star.r,star.angle),1.3,C.ink);if(s.flags.compared)dot(c,X(star.r,star.reference),Y(star.r,star.reference),1.7,C.gold,false);}ball(c,cx,cy,6,C.gold);
 const g=plot(c,w*.62,h*.23,w*.25,h*.41,{xmin:0,xmax:3.5,ymin:0,ymax:2,xlabel:'r',ylabel:'v'});g.curve(r=>P.circularSpeed(r,0),C.gold);g.curve(r=>P.circularSpeed(r,s.values.halo),C.violet);label(c,'Visible',w*.67,h*.77,C.gold,12);label(c,'Visible + halo',w*.75,h*.83,C.violet,12);caption(c,'Toy galaxy: orbit speeds and the rotation curve use the same model.',w,h);}
function expansion(c,w,h,s,t){const tau=t/5,L=s.values.lambda,maxA=P.scaleFactor(2.8,L)*1.08,a=P.scaleFactor(tau,L),base=P.scaleFactor(tau,0),x0=w*.17,span=w*.65,unit=span/maxA;
 for(const [i,size,color,name]of [[0,base,C.gold,'Matter only'],[1,a,C.violet,'Matter + Λ']]){const y=h*(.21+i*.17);dot(c,x0,y,4,color);dot(c,x0+size*unit,y,4,color);path(c,[[x0+5,y],[x0+size*unit-5,y]],color,1.4);label(c,name,x0,y-17,color,12,'left');label(c,`a = ${size.toFixed(2)}`,w*.86,y+4,color,12,'left');}
 const g=plot(c,w*.18,h*.61,w*.62,h*.22,{xmin:0,xmax:2.8,ymin:0,ymax:Math.max(4,maxA),xlabel:'H₀ Δt',ylabel:'a'});g.curve(z=>P.scaleFactor(z,0),C.gold);g.curve(z=>P.scaleFactor(z,L),C.violet);dot(c,g.X(tau),g.Y(a),4,C.violet);caption(c,t>=14?'End of comparison. Replay to start again.':'Both models start at a = 1. Expansion and acceleration are different quantities.',w,h);}
function scales(c,w,h,s){const x=w*.17,ww=w*.67,y=h*.62,exponent=s.values.scale;path(c,[[x,y],[x+ww,y]],C.ink,1.5);for(const e of [-10,-15,-20,-25,-30,-35]){const xx=x+(-10-e)/25*ww;path(c,[[xx,y-5],[xx,y+5]],C.ink);label(c,`10${sup(e)}`,xx,y+25,C.muted,11);}const at=x+(-10-exponent)/25*ww;ball(c,at,y,6,C.rose);
 const cx=w*.5,cy=h*.3;if(exponent>-20){for(let i=0;i<80;i++){const a=i*2.4,r=Math.sqrt(hash(i))*Math.min(w*.13,h*.15);dot(c,cx+Math.cos(a)*r,cy+Math.sin(a)*r,1,C.mint+'80');}label(c,'Quantum probability: an illustration',cx,h*.49,C.mint,12);}else{for(let j=-3;j<=3;j++){const pts=[];for(let i=-18;i<=18;i++)pts.push([cx+i*w*.012,cy+j*h*.035+Math.sin(i*.15)*h*.02]);path(c,pts,s.flags.overlay&&j%2?C.violet:C.line,1.2);}label(c,'?',cx,cy+10,C.rose,44);label(c,'No confirmed picture of Planck-scale geometry',cx,h*.49,C.muted,w<450?10:12);}caption(c,`Length = 10${sup(exponent)} m. A scale map, not a prediction of a spacetime texture.`,w,h);}
function sup(n){return String(n).split('').map(x=>({'-':'⁻','0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹'})[x]||x).join('');}
const questions=[['Black-hole information','What becomes of quantum information?','S_BH = kB A / (4ℓP²)'],['The early universe','Where does the classical description stop?','a → 0 : a limit of the classical model'],['Quantum spacetime','What is the quantum description of geometry?','A complete, experimentally confirmed theory: ?']];
function frontier(c,w,h,s,t){const q=Math.round(s.values.question),cx=w*.5,cy=h*.39,r=Math.min(w*.17,h*.18);if(q===0){dot(c,cx,cy,r*.6,C.ink);ring(c,cx,cy,r,r*.28,C.gold);arrow(c,cx+r,cy-8,35,-20,C.rose);label(c,'?',cx+r+43,cy-27,C.rose,24);}else if(q===1){for(let i=1;i<6;i++){c.save();c.translate(cx,cy);c.rotate(-.2);ring(c,0,0,r*i/5,r*i/9,C.line);c.restore();}dot(c,cx,cy,5,C.rose);}else{for(let j=-4;j<=4;j++){const pts=[];for(let i=-15;i<=15;i++)pts.push([cx+i*r/13,cy+j*r/7+Math.sin(i*.2+t*.3)*r*.025]);path(c,pts,C.line);}label(c,'?',cx,cy+12,C.rose,40);}label(c,questions[q][0],cx,h*.14,C.ink,17);label(c,questions[q][1],cx,h*.72,C.ink,w<450?11:14);label(c,questions[q][2],cx,h*.83,C.muted,w<450?10:12);}
const DRAW={pendulum,action,hamilton,field,induction,circuit,gas,entropy,engine,slit,well,tunnel,curvature,clocks,galaxy,expansion,scales,questions:frontier};
export function drawLab(c,w,h,s,{calm=false,thumb=false}={}){c.clearRect(0,0,w,h);c.fillStyle=C.paper;c.fillRect(0,0,w,h);c.lineCap='round';c.lineJoin='round';c.save();DRAW[s.act.id]?.(c,w,h,s,calm&&thumb?0:s.time);c.restore();}
